import{_ as t,o as a,c as s,a3 as n}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"System design","description":"The architecture and boundaries that protect knowledge, identity and publication.","frontmatter":{"title":"System design","description":"The architecture and boundaries that protect knowledge, identity and publication."},"headers":[],"relativePath":"design/index.md","filePath":"design/index.md","lastUpdated":1794376220000}'),r={name:"design/index.md"};function o(i,e,d,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="design-around-the-evidence" tabindex="-1">Design around the evidence <a class="header-anchor" href="#design-around-the-evidence" aria-label="Permalink to &quot;Design around the evidence&quot;">​</a></h1><p><strong>Rust owns durable state. Workers propose results. The interface exposes authorized views.</strong> The research application is planned; these pages define its contracts.</p><h2 id="the-system-at-a-glance" tabindex="-1">The system at a glance <a class="header-anchor" href="#the-system-at-a-glance" aria-label="Permalink to &quot;The system at a glance&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sources → workers → draft proposals → review → published library</span></span>
<span class="line"><span>                                                   ↓</span></span>
<span class="line"><span>Browser ← streamed answer + citations ← authorized retrieval</span></span></code></pre></div><p>A private Rust store owns transactions. The hosted API and compute workers are replaceable processes attached to that store. Local authoring may embed it. This is a small deployment with clear boundaries, not seven mandatory microservices.</p><h2 id="read-by-responsibility" tabindex="-1">Read by responsibility <a class="header-anchor" href="#read-by-responsibility" aria-label="Permalink to &quot;Read by responsibility&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Canonical document</th></tr></thead><tbody><tr><td>Modules, process roles and state ownership</td><td><a href="./../project/system">System breakdown</a></td></tr><tr><td>Artifacts, identities, claims and portable packages</td><td><a href="./../project/knowledge">Knowledge and identity</a></td></tr><tr><td>Chat, evidence, cancellation and reconnect</td><td><a href="./../project/streaming">Streaming interface</a></td></tr><tr><td>Leases, capabilities, native workers and permissions</td><td><a href="./../project/plugins">Workers and jobs</a></td></tr><tr><td>Chosen directions and open alternatives</td><td><a href="./../project/decisions">Decision register</a></td></tr><tr><td>Observable requirements</td><td><a href="./../project/acceptance">Acceptance register</a></td></tr></tbody></table><h2 id="two-profiles-one-set-of-rules" tabindex="-1">Two profiles, one set of rules <a class="header-anchor" href="#two-profiles-one-set-of-rules" aria-label="Permalink to &quot;Two profiles, one set of rules&quot;">​</a></h2><p><strong>Authoring:</strong> import, extract, resolve, review and publish on an authorized workstation.</p><p><strong>Hosted demonstration:</strong> serve an approved snapshot and separate conversation records. Do not independently edit the research graph in version one.</p><p>Export/import connects the profiles. It is not concurrent synchronization of a live database file.</p><h2 id="non-negotiable-boundaries" tabindex="-1">Non-negotiable boundaries <a class="header-anchor" href="#non-negotiable-boundaries" aria-label="Permalink to &quot;Non-negotiable boundaries&quot;">​</a></h2><p>Names and vectors generate candidates; they do not authorize merges. Source confidence is separate from claim assessment. Publication is a reviewed transaction. Model output cannot grant access. Public export physically excludes private records and artifacts.</p><p>The <a href="./../engineering/twelve-factor">twelve-factor matrix</a> explains hosted process requirements and the local-appliance exception.</p><p><strong>Next:</strong> <a href="./../project/system">Read the system breakdown →</a></p>`,15)])])}const b=t(r,[["render",o]]);export{u as __pageData,b as default};
